/* @lc app=leetcode id=954 lang=kotlin */ class Solution { fun canReorderDoubled(arr: IntArray): Boolean = arr.toList().groupingBy { it }.eachCount().toMutableMap().let { m -> arr.sortedBy { Math.abs(it) }.all { x -> m[x] == 0 || m.getOrDefault(2 * x, 0) > (if (x == 0) 1 else 0) && m.merge(x, -1) { a, b -> a + b }.let { true } && m.merge(2 * x, -1) { a, b -> a + b }.let { true } } } }